+/// Whether [segment] can be safely joined under a trusted directory:
+/// rejects path separators and `.`/`..` (E4 path-escape guard).
+bool isSafePathSegment(String segment) =>
+    segment.isNotEmpty &&
+    segment != '.' &&
+    segment != '..' &&
+    !segment.contains('/') &&
+    !segment.contains(r'\');
