+  /// Creates a configuration; see each field for its default.
+  const SessionRetentionConfig({
+    this.maxTotalBytes = 0,
+    this.minAgeDays = defaultMinAgeDays,
+    this.keepNamed = true,
+    this.sweep = SessionRetentionSweepMode.boot,
+    this.notes = const [],
+  });
