    );
    if (metadata != null) {
      if (matches.length > 1) {
        io.writeln(
          _style.dim(
            "note: ${matches.length} sessions named '$name' — opened "
            '${metadata.id} (${metadata.cwd}); pick another with '
            '/sessions or restart with fa --session <id>',
