+      minAgeDays: minAgeDays,
+      keepNamed: keepNamed,
+      sweep: sweep,
+      notes: List.unmodifiable(notes),
+    );
+  }
+
+  static int _intWithNote(
+    Object? value,
+    int fallback,
+    String name,
+    List<String> notes,
+  ) {
+    if (value is int) return value;
+    if (value is num) return value.round();
+    notes.add('$name: not a number, default applied');
