+  /// When the sweep runs (default [SessionRetentionSweepMode.boot]).
+  final SessionRetentionSweepMode sweep;
+
+  /// Tolerant-parse notes (unknown keys, mistyped scalars) surfaced at
+  /// boot; never fatal.
+  final List<String> notes;
