+  String toYaml({int indent = 2}) {
+    if (!hasExplicitValues) return '';
+    final pad = ' ' * indent;
+    final inner = ' ' * (indent + 2);
+    final buffer = StringBuffer('${pad}retention:\n');
+    if (maxTotalBytes != 0) {
+      buffer.write('${inner}maxTotalBytes: $maxTotalBytes\n');
