            !args[i].startsWith('-')) {
          repairTarget = args[i];
          continue;
        }
        throw CliArgsException('unknown argument: ${args[i]}\n$_sessionUsage');
    }
  }
  return (json: json, flat: flat, dryRun: dryRun, repairTarget: repairTarget);
}

